%[text] Start by establishing the sub-structure as a struct.
% Initialize the model structure
clc; clear all;
% Load config struct for base_support
base_support = config_base_support();
%[text] Next use the gen\_structure function to create the mass, stiffness, and mapping matrices.
base_support = fem.generate_fem_matrices(base_support);
% Display to show how function operatres (not necessary)
base_support.K %[output:672e71c0]
base_support.M %[output:29790a3e]
base_support.mapping %[output:57c97503]
%[text] Verify matrecies through printouts and then use plotting functions for further verification
% Visualize the assembled FEM model
fem.plot_fem_model(base_support); %[output:308bcf32]
%[text] Simulate a harmonic disturbance in the x and y axes at the top of the structure.
% Define time parameters and generate the time vector
fs = 1000; % Example sampling frequency in Hz
t_span = [0, 20];
t = t_span(1) : 1/fs : t_span(2);

% Initialize options struct
options_test_1 = struct();
options_test_1.t = t;
options_test_1.z = 0.01;

% Define the harmonic profile (e.g., 2 Hz, 0.1 amplitude)
harmonic_profile = 0.1 * cos(2 * pi * 2 * t);

% Create the forces struct array for X and Y on the top node
options_test_1.forces(1) = struct('node_id', "Top", 'dof', "x", 'profile', harmonic_profile);
options_test_1.forces(2) = struct('node_id', "Top", 'dof', "y", 'profile', harmonic_profile);
[X_rms_base_support, X_base_support] = fem.calculate_plot_rms(base_support, options_test_1); %[output:5b16fb5e]
%[text] Define a second structure attached to the first using the same struct hierarchy as before.
tower = config_tower();
%[text] Combine with the base support to form a single larger structure
building = fem.merge_fem_models(base_support, tower);
% Visualize the fully assembled FEM model
fem.plot_fem_model(building); %[output:44b5d662]
%[text] Find X\_RMS of the new combinded structure using harmonics along the tower and not just at its base.
% Initialize options struct, use value of t from before
options_test_2 = struct();
options_test_2.t = t;
options_test_2.z = 0.01;

% Define the harmonic profile (e.g., 0.5 Hz, 0.1 amplitude)
harmonic_profile = 0.1 * cos(2 * pi * 0.5 * t);

% Create the forces struct array for X and Y on the top node
options_test_2.forces(1) = struct('node_id', "Middle Joint", 'dof', "x", 'profile', harmonic_profile);
options_test_2.forces(2) = struct('node_id', "Top Joint", 'dof', "x", 'profile', harmonic_profile);
[X_rms_building, X_building] = fem.calculate_plot_rms(building, options_test_2); %[output:70b71a9c]

